  '150c': { name: 'Ammonia caramel (Class III)', cls: 'Colour — processed caramel', verdict: 'bad', risk: 'moderate', organs: { immune: 2, metabolic: 1 }, harm: 'Made with ammonia compounds; contains THI (2-acetyl-tetrahydroxybutylimidazole), an immune-suppressant in animal studies that lowers white blood cell counts.', symptoms: 'None acute; immune effects are silent', adi: '100 mg/kg bw/day', law: 'Permitted with THI purity limits.' },
  '150d': { name: 'Sulphite ammonia caramel (Class IV)', cls: 'Colour — processed caramel', verdict: 'bad', risk: 'high', organs: { cancer: 3, liver: 1 }, harm: 'The cola caramel. Manufactured with ammonia + sulphites at high heat, creating 4-methylimidazole (4-MEI) — classified by IARC as possibly carcinogenic (Group 2B) after lung-tumour findings in mice. California Prop-65 forces warning labels above 29 µg/day exposure.', symptoms: 'None acute — risk is cumulative', adi: '200 mg/kg bw/day', law: 'California requires a cancer warning above the 4-MEI threshold; soft-drink makers reformulated US recipes but often not elsewhere.' },
