  '211': { name: 'Sodium benzoate', cls: 'Preservative', verdict: 'bad', risk: 'high', organs: { brain: 2, immune: 2, cancer: 2, skin: 1 }, harm: 'The soft-drink preservative. With vitamin C (E300) and heat/light it can form BENZENE — a proven human carcinogen (leukaemia); regulators audit drinks for this. Southampton research linked benzoate + colour mixes to child hyperactivity; also a histamine liberator.', symptoms: 'Hyperactivity, hives, asthma aggravation', adi: '5 mg/kg bw/day (group)', law: 'Permitted worldwide but benzene-formation in drinks is monitored; many brands reformulated.' },
  '212': { name: 'Potassium benzoate', cls: 'Preservative', verdict: 'bad', risk: 'moderate', organs: { immune: 2, cancer: 1 }, harm: 'As sodium benzoate, including the benzene-formation pathway with vitamin C.', symptoms: 'As E211', adi: '5 mg/kg bw/day (group)', law: 'Approved with limits.' },
  '213': { name: 'Calcium benzoate', cls: 'Preservative', verdict: 'bad', risk: 'moderate', organs: { immune: 2 }, harm: 'As benzoic acid.', symptoms: 'As E210', adi: '5 mg/kg bw/day (group)', law: 'Approved with limits.' },
  '214': { name: 'Ethylparaben', cls: 'Preservative — paraben', verdict: 'bad', risk: 'high', organs: { hormone: 3, immune: 1 }, harm: 'Parabens are xenoestrogens — they mimic oestrogen, and food-grade propyl/ethyl forms showed effects on male reproductive hormones in animal studies. The EU revoked propylparaben’s food approval for this reason.', symptoms: 'None acute; endocrine effects are silent', adi: '0–10 mg/kg bw/day (ethyl/methyl group)', law: 'Propylparaben (E216) banned in EU food since 2006; ethyl/methyl still permitted in limited uses.' },
