  '218': { name: 'Methylparaben', cls: 'Preservative — paraben', verdict: 'bad', risk: 'moderate', organs: { hormone: 2, skin: 1 }, harm: 'Weakest oestrogenic activity of the parabens; still part of cumulative endocrine load. Rare contact allergy.', symptoms: 'Rare rash', adi: '10 mg/kg bw/day (group)', law: 'Permitted in limited uses.' },
  '220': { name: 'Sulphur dioxide', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'high', organs: { lungs: 3, immune: 2, gut: 1 }, harm: 'Gas used on dried fruit, wine, juices. The leading additive cause of ASTHMA ATTACKS — bronchospasm can be rapid and severe in the ~5% of asthmatics who are sulphite-sensitive; destroys thiamine (vitamin B1) in food; headaches and gut irritation reported.', symptoms: 'Wheezing, chest tightness, flushing, headache, stomach irritation', adi: '0.7 mg/kg bw/day (group)', law: 'Mandatory allergen-style declaration above 10 mg/kg in EU/US/India.' },
  '221': { name: 'Sodium sulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'high', organs: { lungs: 3, immune: 2 }, harm: 'As E220 — asthma trigger, B1 destroyer.', symptoms: 'As E220', adi: '0.7 mg/kg bw/day (group)', law: 'Declaration mandatory above 10 mg/kg.' },
  '222': { name: 'Sodium bisulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'high', organs: { lungs: 3, immune: 2 }, harm: 'As E220.', symptoms: 'As E220', adi: '0.7 mg/kg bw/day (group)', law: 'Declaration mandatory.' },
  '223': { name: 'Sodium metabisulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'high', organs: { lungs: 3, immune: 2, gut: 1 }, harm: 'Common in Indian snacks, jams, drink concentrates. Releases sulphur dioxide in the stomach; potent asthma trigger and vitamin-B1 destroyer; anaphylactoid reactions documented.', symptoms: 'Wheeze, hives, cramps, headache', adi: '0.7 mg/kg bw/day (group)', law: 'Declaration mandatory above 10 mg/kg.' },
  '224': { name: 'Potassium metabisulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'high', organs: { lungs: 3, immune: 2 }, harm: 'As E223 (wine, fruit products).', symptoms: 'As E223', adi: '0.7 mg/kg bw/day (group)', law: 'Declaration mandatory.' },
  '226': { name: 'Calcium sulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'moderate', organs: { lungs: 2, immune: 2 }, harm: 'As the sulphite group.', symptoms: 'As E220', adi: '0.7 mg/kg bw/day (group)', law: 'EU delisted; others restrict.' },
  '228': { name: 'Potassium bisulphite', cls: 'Preservative — sulphite', verdict: 'bad', risk: 'moderate', organs: { lungs: 2, immune: 2 }, harm: 'As the sulphite group.', symptoms: 'As E220', adi: '0.7 mg/kg bw/day (group)', law: 'Restricted uses.' },
  '234': { name: 'Nisin', cls: 'Preservative — natural bacteriocin', verdict: 'neutral', risk: 'low', organs: {}, harm: 'Peptide from dairy fermentation bacteria; digested like protein. Theoretical antibiotic-resistance crossover is monitored, not demonstrated.', symptoms: '', adi: '2 mg/kg bw/day', law: 'Approved worldwide (cheese, paneer).' },
  '235': { name: 'Natamycin', cls: 'Preservative — antifungal', verdict: 'neutral', risk: 'low', organs: { gut: 1 }, harm: 'Antifungal antibiotic for cheese/meat surfaces; barely absorbed. Concern is breeding antifungal resistance, so it is limited to rind treatment.', symptoms: 'Nausea at gross overdose only', adi: '0.3 mg/kg bw/day', law: 'Surface treatment only in the EU.' },
  '239': { name: 'Hexamethylene tetramine', cls: 'Preservative', verdict: 'bad', risk: 'high', organs: { cancer: 2, kidney: 2, skin: 1 }, harm: 'Releases FORMALDEHYDE (a human carcinogen) as it works; restricted to one Italian cheese in the EU. Bladder irritation and gene-damage concerns at higher exposures.', symptoms: 'None at permitted trace; formaldehyde risk is cumulative', adi: '0.15 mg/kg bw/day', law: 'EU: Provolone cheese only. Banned elsewhere in most foods.' },
  '242': { name: 'Dimethyl dicarbonate', cls: 'Preservative — cold steriliser', verdict: 'neutral', risk: 'low', organs: {}, harm: 'Added to drinks where it fully breaks down to CO2 + methanol traces within hours; nothing remains by drinking time.', symptoms: '', adi: 'Not specified (fully decomposes)', law: 'Approved for beverages.' },
  '249': { name: 'Potassium nitrite', cls: 'Preservative — cured meat', verdict: 'bad', risk: 'high', organs: { cancer: 3, heart: 1, brain: 1 }, harm: 'Cured-meat nitrite. Forms NITROSAMINES (potent carcinogens) with meat proteins at high heat — the key reason IARC classifies processed meat as Group 1 (carcinogenic to humans, colorectal cancer). Infants are vulnerable to methaemoglobinaemia (blue-baby oxygen starvation).', symptoms: 'None acute at legal doses; cancer risk is cumulative', adi: '0.07 mg/kg bw/day', law: 'Strict residual limits; EU cut limits again in 2023; banned in baby food.' },
  '250': { name: 'Sodium nitrite', cls: 'Preservative — cured meat', verdict: 'bad', risk: 'high', organs: { cancer: 3, heart: 1, brain: 1 }, harm: 'As E249 — the salami/bacon/ham pink-curing salt. Nitrosamine formation links processed meat to colorectal and stomach cancer; WHO advises minimising processed-meat intake entirely.', symptoms: 'Headache/flushing at high doses; cancer risk cumulative', adi: '0.07 mg/kg bw/day', law: 'EU tightened limits 2023; "uncured/no-added-nitrite" labels often just use celery-powder nitrate instead.' },
  '251': { name: 'Sodium nitrate', cls: 'Preservative — cured meat', verdict: 'bad', risk: 'high', organs: { cancer: 2, hormone: 1, heart: 1 }, harm: 'Converts to nitrite in saliva, then follows the nitrosamine pathway. Chronic high intake also competes with iodine uptake in the thyroid.', symptoms: 'None acute', adi: '3.7 mg/kg bw/day', law: 'Restricted as E250.' },
  '252': { name: 'Potassium nitrate', cls: 'Preservative — cured meat', verdict: 'bad', risk: 'high', organs: { cancer: 2, heart: 1 }, harm: 'As E251 (saltpetre).', symptoms: '', adi: '3.7 mg/kg bw/day', law: 'Restricted.' },
