// Lookup that tolerates 'INS 102', 'E102', '102', 'e-102', '150 d', '500(ii)' etc.
export function additiveInfo(codeRaw) {
  if (!codeRaw) return null
  let c = String(codeRaw).toLowerCase().replace(/^(ins|e)[\s.-]*/i, '').replace(/\s+/g, '')
  c = c.replace(/\((i+v?|v)\)$/, '')          // roman sub-codes: 500(ii) -> 500
  if (ADDITIVES[c]) return { code: c, ...ADDITIVES[c] }
  const base = c.replace(/[a-d]$/, '')        // 160a -> 160 fallback
  if (ADDITIVES[base]) return { code: base, ...ADDITIVES[base] }
  return null
}

export const ADDITIVE_COUNT = Object.keys(ADDITIVES).length
